import java.util.*;
import java.io.*;

public class Main {
    static int[] findValues(int[] a, int[] b, int[] c) {
        // Write your solution here
        // Return {answer for task 1, answer for task 2, answer for task 3}
        return new int[]{0, 0, 0};
    }

    static int[] readArray(StreamTokenizer in, int len) throws IOException {
        int[] x = new int[len];
        for (int i = 0; i < len; i++) {
            in.nextToken();
            x[i] = (int) in.nval;
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int[] a = readArray(in, (int) in.nval);
        in.nextToken();
        int[] b = readArray(in, (int) in.nval + 1);
        in.nextToken();
        int[] c = readArray(in, (int) in.nval + 1);
        int[] res = findValues(a, b, c);
        StringBuilder sb = new StringBuilder();
        for (int v : res) sb.append(v).append("\n");
        System.out.print(sb);
    }
}
